files.config/load.go:
package config

import (
	"encoding/json"
	"os"
	"strconv"
)

// Settings is the effective configuration of the service.
type Settings struct {
	TimeoutMS    int    `json:"timeout_ms"`
	Retries      int    `json:"retries"`
	Region       string `json:"region"`
	TimeoutScale int    `json:"timeout_scale"`
}

// Load layers the configuration: the compiled-in defaults, then
// config.json, then profiles/base.json, then the profile named by
// APP_PROFILE. The timeout is then multiplied by the scale, and
// APP_TIMEOUT_MS, when set, replaces the result.
func Load() (Settings, error) {
	s := Defaults
	if err := overlay(&s, "config.json"); err != nil {
		return s, err
	}
	if err := overlay(&s, "profiles/base.json"); err != nil {
		return s, err
	}
	if p := os.Getenv("APP_PROFILE"); p != "" {
		if err := overlay(&s, "profiles/"+p+".json"); err != nil {
			return s, err
		}
	}
	if s.TimeoutScale > 1 {
		s.TimeoutMS *= s.TimeoutScale
	}
	if v := os.Getenv("APP_TIMEOUT_MS"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil {
			return s, err
		}
		s.TimeoutMS = n
	}
	return s, nil
}

// overlay applies a JSON file's fields onto s; keys the file does not
// mention keep the value they already had, and a missing file is not an
// error.
func overlay(s *Settings, path string) error {
	b, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return err
	}
	return json.Unmarshal(b, s)
}

