package main

import (
	"fmt"
	"os"

	"example.com/svc/config"
)

func main() {
	s, err := config.Load()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Printf("timeout_ms=%d retries=%d region=%s\n", s.TimeoutMS, s.Retries, s.Region)
}

